#define bgColor vec3(0.39215, 0.1176, 0.2039) 
#define fgColor vec3(0.3412, 0.0784, 0.1608) 

vec2 random2(vec2 st) {
    st = vec2(dot(st, vec2(127.1f, 311.7f)), dot(st, vec2(269.5f, 183.3f)));
    return -1.0f + 2.0f * fract(sin(st) * 43758.5453123f);
}

float noisegradient(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    vec2 u = f * f * (3.0f - 2.0f * f);

    return mix(mix(dot(random2(i + vec2(0.0f, 0.0f)), f - vec2(0.0f, 0.0f)), dot(random2(i + vec2(1.0f, 0.0f)), f - vec2(1.0f, 0.0f)), u.x), mix(dot(random2(i + vec2(0.0f, 1.0f)), f - vec2(0.0f, 1.0f)), dot(random2(i + vec2(1.0f, 1.0f)), f - vec2(1.0f, 1.0f)), u.x), u.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 st = gl_FragCoord.xy / iResolution.xy * 2.f;
    float t = 1.0f;
    // Scale the coordinate system to see
    // some noise in action
    //t = abs(sin(u_time * .1) + 0.3) * 5.;
    t = 2.5f;
    st += noisegradient(st * 2.f) * t;
    /* st += iMouse * 0.001f; */
    st += iTime * 0.05f;
    vec2 pos = vec2(st * 10.0f);
    // Use the noise function
    float n = noisegradient(pos);

    fragColor = vec4(vec3(n), 1.0f);

  //Distance field
    fragColor = vec4(vec3(fract(n * 10.f)), 1.0f);

    vec3 color = vec3(0.0f);

    color = vec3(mix(bgColor, fgColor, smoothstep(0.03f, 0.04f, n)));
    ;

    fragColor = vec4(color, 1.0f);
}
